const gpu = new GPU({ mode });

const smooth = gpu.createKernel(function (signal) {
  let sum = 0;
  for (let d = 0; d < 5; d++) {
    const j = Math.max(0, Math.min(this.constants.n - 1, this.thread.x + d - 2));
    sum += signal[j];
  }
  return sum / 5;
}, {
  output: [128],
  constants: { n: 128 },
});

const result = smooth(signal);
